        for job in options:
            if len(chosen) == data["k"]:
                break
            if job["value"] < 0:
                continue
            trial = chosen + [job]
            # Build a locally compatible choice, then check the final quotas.
            stripped = {"mandatory": [], "quotas": {}}
            if allowed(trial, stripped):
